 public class ReviewActivity {public string id,name,kind,opened;public double progress;}
 public class SourceAnchor {public string itemId,text="";public int chapter,page,start,end;public double time,endTime,x,y,width,height;}
 public class ClipRecord {public string id,title,text,created;public SourceAnchor source;public List<string> tags=new List<string>();}
 public class SpaceRecord {public string id,name,created,view="grid";public List<string> members=new List<string>();public Dictionary<string,CanvasPoint> positions=new Dictionary<string,CanvasPoint>();}
 public class CanvasPoint {public double x,y;}
 public class CollectionQuery {public string id,name,query="",kind="",tag="",ext="";public bool unread;public int days;}
 public class RecipeStep {public string capability;public Dictionary<string,object> args=new Dictionary<string,object>();}
 public class RecipeRecord {public string id,name;public List<RecipeStep> steps=new List<RecipeStep>();}
 public class ResourcePatch {public string kind,id,before,after;}
 public class WorkspaceState {
  public List<ClipRecord> clips=new List<ClipRecord>();public List<SpaceRecord> spaces=new List<SpaceRecord>();public List<CollectionQuery> queries=new List<CollectionQuery>();public List<RecipeRecord> recipes=new List<RecipeRecord>();
  public IEnumerable<KnowledgeLink> Links(){foreach(var c in clips)yield return new KnowledgeLink{source=c.id,target=c.source.itemId,kind="clip",title=c.title};foreach(var s in spaces)foreach(var id in s.members)yield return new KnowledgeLink{source=s.id,target=id,kind="space",title=s.name};}
 }
 public partial class Library {
  Operation ApplyResources(Operation op,bool undo){foreach(var p in op.resources){ValidateResource(p.kind,p.id,undo?p.before:p.after);if(ResourceValue(p.kind,p.id)!=(undo?p.after:p.before))throw new InvalidOperationException("内容已被修改，已保留当前内容。请重新查看后再操作。");}string prior=op.state;try{foreach(var p in op.resources)ResourceAssign(p,!undo);op.state=undo?"undone":"applied";if(undo)op.undoneBy=Guid.NewGuid().ToString("N");Save(false,op.resources.Where(p=>p.kind=="item").Select(p=>p.id),new[]{op.id},true);}catch{foreach(var p in op.resources)ResourceAssign(p,undo);op.state=prior;op.undoneBy=null;throw;}return Json.Deserialize<Operation>(Json.Serialize(op));}
  public object WorkspaceSnapshot(){lock(gate)return Json.Deserialize<WorkspaceState>(Json.Serialize(Db.workspace));}
  static string CanonicalResource(string kind,string json){if(json==null)return null;if(kind=="space")return Json.Serialize(Json.Deserialize<SpaceRecord>(json));if(kind=="clip")return Json.Serialize(Json.Deserialize<ClipRecord>(json));if(kind=="query")return Json.Serialize(Json.Deserialize<CollectionQuery>(json));return Json.Serialize(Json.Deserialize<RecipeRecord>(json));}
  internal string ResourceValue(string kind,string id){object value=kind=="item"?(object)Find(id):kind=="space"?(object)Db.workspace.spaces.FirstOrDefault(s=>s.id==id):kind=="clip"?Db.workspace.clips.FirstOrDefault(s=>s.id==id):kind=="query"?Db.workspace.queries.FirstOrDefault(s=>s.id==id):kind=="recipe"?Db.workspace.recipes.FirstOrDefault(s=>s.id==id):null;return value==null?null:Json.Serialize(value);}
  internal void ResourceAssign(ResourcePatch p,bool after){string json=after?p.after:p.before;if(p.kind=="item"){Db.items.RemoveAll(e=>e.id==p.id);if(json!=null){var item=Json.Deserialize<Entry>(json);Db.items.Add(item);Db.ignoredAutoPaths.RemoveAll(path=>String.Equals(path,item.path,StringComparison.OrdinalIgnoreCase));}}else if(p.kind=="space"){Db.workspace.spaces.RemoveAll(s=>s.id==p.id);if(json!=null)Db.workspace.spaces.Add(Json.Deserialize<SpaceRecord>(json));}else if(p.kind=="clip"){Db.workspace.clips.RemoveAll(s=>s.id==p.id);if(json!=null)Db.workspace.clips.Add(Json.Deserialize<ClipRecord>(json));}else if(p.kind=="query"){Db.workspace.queries.RemoveAll(s=>s.id==p.id);if(json!=null)Db.workspace.queries.Add(Json.Deserialize<CollectionQuery>(json));}else if(p.kind=="recipe"){Db.workspace.recipes.RemoveAll(s=>s.id==p.id);if(json!=null)Db.workspace.recipes.Add(Json.Deserialize<RecipeRecord>(json));}else throw new InvalidDataException("工作区对象类型无效。");}
  internal void ValidateResource(string kind,string id,string json){if(!AgentJournal.ValidId(id)||!new[]{"space","clip","query","recipe","item"}.Contains(kind)||json!=null&&json.Length>8*1024*1024)throw new InvalidDataException("工作区对象无效。");if(json==null)return;if(kind=="item"){var item=Json.Deserialize<Entry>(json);if(item==null||item.id!=id||String.IsNullOrEmpty(item.path))throw new InvalidDataException("工作区对象无效。");return;}
   if(kind=="space"){var s=Json.Deserialize<SpaceRecord>(json);if(s.id!=id||String.IsNullOrWhiteSpace(s.name)||s.name.Length>100||!new[]{"grid","canvas","timeline","graph"}.Contains(s.view)||s.members==null||s.members.Count>5000||s.members.Distinct().Count()!=s.members.Count||s.members.Any(k=>String.IsNullOrWhiteSpace(k)||k.Length>100||k.Any(ch=>!Char.IsLetterOrDigit(ch)&&ch!='_'&&ch!='-'))||s.positions==null||s.positions.Values.Any(p=>p==null||Double.IsNaN(p.x)||Double.IsInfinity(p.x)||Double.IsNaN(p.y)||Double.IsInfinity(p.y)||Math.Abs(p.x)>100000||Math.Abs(p.y)>100000))throw new InvalidDataException("空间内容无效。");}
   if(kind=="clip"){var c=Json.Deserialize<ClipRecord>(json);if(c.id!=id||c.source==null||String.IsNullOrWhiteSpace(c.source.itemId)||c.source.itemId.Length>100||c.source.itemId.Any(ch=>!Char.IsLetterOrDigit(ch)&&ch!='_'&&ch!='-')||(c.text??"").Length>200000||(c.title??"").Length>200||c.source.start<0||c.source.end<c.source.start||c.source.time<0||c.source.endTime<c.source.time||new[]{c.source.time,c.source.endTime,c.source.x,c.source.y,c.source.width,c.source.height}.Any(v=>Double.IsNaN(v)||Double.IsInfinity(v))||c.source.chapter<0||c.source.page<0||c.source.x<0||c.source.y<0||c.source.width<0||c.source.height<0||c.source.x+c.source.width>1.001||c.source.y+c.source.height>1.001)throw new InvalidDataException("摘录来源或范围无效。");}
   if(kind=="query"){var q=Json.Deserialize<CollectionQuery>(json);if(q.id!=id||String.IsNullOrWhiteSpace(q.name)||q.name.Length>100||q.days<0||q.days>36500||(q.query??"").Length>200||!new[]{"","video","photo","music","document","book"}.Contains(q.kind))throw new InvalidDataException("智能集合条件无效。");}
   if(kind=="recipe"){var r=Json.Deserialize<RecipeRecord>(json);if(r.id!=id||String.IsNullOrWhiteSpace(r.name)||r.name.Length>100||r.steps==null||r.steps.Count<1||r.steps.Count>20)throw new InvalidDataException("配方内容无效。");foreach(var step in r.steps){var cap=ModuleRegistry.Builtins.Capabilities.FirstOrDefault(c=>c.id==step.capability&&c.surfaces.Contains("recipe"));if(cap==null||step.args==null)throw new InvalidDataException("配方包含不可用能力。");}}
  }
  public Operation ProposeResource(string kind,string id,string json,string source="user",string operationId=null){lock(gate){operationId=operationId??OperationOrigin.Id;source=OperationOrigin.Source??source;if(operationId!=null){var previous=FindOperation(operationId);if(previous!=null)return previous;}ValidateResource(kind,id,json);json=CanonicalResource(kind,json);var p=new ResourcePatch{kind=kind,id=id,before=ResourceValue(kind,id),after=json};if(p.before==null&&p.after==null)throw new InvalidDataException("对象已移除。");var op=new Operation{id=operationId??Guid.NewGuid().ToString("N"),module="workspace",source=source,title=kind=="clip"?"编辑摘录":kind=="space"?"编辑空间":kind=="query"?"编辑智能集合":"编辑配方",created=DateTime.UtcNow.ToString("o"),resources=new List<ResourcePatch>{p}};CheckOpCapacity(op);OperationRows.Add(op);try{Save(false,new string[0],new[]{op.id});}catch{OperationRows.Remove(op);throw;}return op;}}
  public List<string> QueryCollection(CollectionQuery q){lock(gate){ValidateResource("query",q.id,Json.Serialize(q));HashSet<string> search=String.IsNullOrWhiteSpace(q.query)?null:new HashSet<string>(FullTextSearch(q.query));return Db.items.Where(i=>(q.kind==""||i.kind==q.kind)&&(q.ext==""||String.Equals(i.ext,q.ext,StringComparison.OrdinalIgnoreCase))&&(q.tag==""||i.tags.Contains(q.tag))&&(!q.unread||i.progress<=0)&& (q.days==0||String.CompareOrdinal(i.added,DateTime.UtcNow.AddDays(-q.days).ToString("o"))>=0)&&(search==null||search.Contains(i.id))).Select(i=>i.id).ToList();}}
  public object ReviewTimeline(){lock(gate){var recent=Db.items.Where(i=>!String.IsNullOrEmpty(i.opened)).Select(i=>new ReviewActivity{id=i.id,name=i.name,kind=i.kind,opened=i.opened,progress=i.progress});var days=store.Activities().Concat(recent).GroupBy(i=>i.opened.Substring(0,Math.Min(10,i.opened.Length))+"|"+i.id).Select(g=>g.OrderByDescending(i=>i.opened).First()).OrderByDescending(i=>i.opened).ToList();return new{opened=days,clips=Db.workspace.clips.OrderByDescending(c=>c.created),operations=OperationRows.Where(o=>o.state=="applied"||o.state=="undone").OrderByDescending(o=>o.created).Take(200)};}}

  public List<string> FullTextSearch(string query){lock(gate)return store.Search(query);}
  public string CachedRecipeSummary(string key){lock(gate)return store.CachedSummary(key);}
  public void CacheRecipeSummary(string key,string text){lock(gate)store.CacheSummary(key,text);}
  public object SpaceLinks(string id){if(!IsPrivate)BuildKnowledgeIndex();lock(gate){var space=Db.workspace.spaces.FirstOrDefault(s=>s.id==id);if(space==null)throw new InvalidDataException("空间内容无效。");var ids=new HashSet<string>(space.members);return store.Relations().Where(l=>ids.Contains(l.source)&&ids.Contains(l.target)).ToList();}}
  public object StorageInfo(){lock(gate)return store.Info();}
  public void IndexItem(Entry item,string text){lock(gate){if(Find(item.id)==null)return;store.Index(item.id,text.Length>2000000?text.Substring(0,2000000):text,item.modified??"");}}
 }
